#include <gtest/gtest.h>

#include <filesystem>
#include <fstream>
#include <sstream>
#include <string>

#include <nlohmann/json.hpp>

#include "zetta/parquet/metadata.hpp"

// Native Parquet footer/metadata parser (ADR-32 / #505). The acceptance: given a
// real Parquet fixture, return its schema + row-group / column-chunk layout, and
// match it against a Python(pyarrow)-dumped golden (an *independent* reference;
// dev-time only — no foreign runtime in the build or CI, ADR-17).
//
// The fixture + golden under tests/fixtures/parquet are regenerated by
// scripts/gen-parquet-fixture.py (needs pyarrow, run by hand). The golden is in
// the exact shape zetta::parquet::to_json emits, so the check is a direct
// equality plus a schema-boundary validation of the golden itself.
namespace {

namespace fs = std::filesystem;
using zetta::parquet::CompressionCodec;
using zetta::parquet::PhysicalType;

fs::path parquet_dir() { return fs::path(ZETTA_TEST_FIXTURES_DIR) / "parquet"; }
fs::path fixture_path() { return parquet_dir() / "churn_sample.parquet"; }
fs::path golden_path() { return parquet_dir() / "churn_sample.metadata.json"; }

// Read a whole file as raw bytes (binary-safe).
std::string read_bytes(const fs::path& path) {
    std::ifstream stream(path, std::ios::binary);
    std::ostringstream buffer;
    buffer << stream.rdbuf();
    return buffer.str();
}

nlohmann::json read_golden() {
    std::ifstream stream(golden_path());
    std::ostringstream buffer;
    buffer << stream.rdbuf();
    return nlohmann::json::parse(buffer.str());
}

}  // namespace

// The headline acceptance: parse the fixture and match the pyarrow golden field
// for field (schema leaf columns + the full row-group / column-chunk layout).
TEST(ParquetMetadata, MatchesPyarrowGolden) {
    const std::string bytes = read_bytes(fixture_path());
    ASSERT_FALSE(bytes.empty()) << "missing fixture " << fixture_path();

    const auto result = zetta::parquet::parse_parquet_metadata(bytes);
    ASSERT_TRUE(result.ok()) << result.error;

    const nlohmann::json golden = read_golden();
    EXPECT_EQ(zetta::parquet::to_json(result.metadata), golden);
}

// The golden is committed external data, so it is validated at the boundary
// against the schema-as-code source of truth before it is trusted.
TEST(ParquetMetadata, GoldenPassesTheSchemaBoundary) {
    const nlohmann::json golden = read_golden();
    EXPECT_EQ(zetta::parquet::validate_parquet_metadata_json(golden), "");
}

TEST(ParquetMetadata, MalformedMetadataJsonFailsTheBoundary) {
    // num_rows must be an integer, not a string.
    nlohmann::json bad = read_golden();
    bad["num_rows"] = "lots";
    EXPECT_NE(zetta::parquet::validate_parquet_metadata_json(bad), "");

    // A column chunk missing a required field fails too.
    nlohmann::json missing = read_golden();
    missing["row_groups"][0]["columns"][0].erase("data_page_offset");
    EXPECT_NE(zetta::parquet::validate_parquet_metadata_json(missing), "");
}

// The decoded schema: the data-bearing columns, in order, with physical types.
TEST(ParquetMetadata, DecodesSchemaColumns) {
    const std::string bytes = read_bytes(fixture_path());
    const auto result = zetta::parquet::parse_parquet_metadata(bytes);
    ASSERT_TRUE(result.ok()) << result.error;

    const auto columns = result.metadata.leaf_columns();
    ASSERT_EQ(columns.size(), 5u);
    EXPECT_EQ(columns[0].path, "account_id");
    EXPECT_EQ(columns[0].type, PhysicalType::Int64);
    EXPECT_EQ(columns[1].path, "risk_score");
    EXPECT_EQ(columns[1].type, PhysicalType::Double);
    EXPECT_EQ(columns[2].path, "failed_payments");
    EXPECT_EQ(columns[2].type, PhysicalType::Int64);
    EXPECT_EQ(columns[3].path, "is_churned");
    EXPECT_EQ(columns[3].type, PhysicalType::Boolean);
    EXPECT_EQ(columns[4].path, "segment");
    EXPECT_EQ(columns[4].type, PhysicalType::ByteArray);

    EXPECT_EQ(result.metadata.num_rows, 6);
    EXPECT_EQ(result.metadata.version, 2);
    EXPECT_FALSE(result.metadata.created_by.empty());
}

// The per-column-chunk layout: codecs, dictionary-page presence, and ordered
// row groups — the layout decoders consume.
TEST(ParquetMetadata, DecodesRowGroupAndChunkLayout) {
    const std::string bytes = read_bytes(fixture_path());
    const auto result = zetta::parquet::parse_parquet_metadata(bytes);
    ASSERT_TRUE(result.ok()) << result.error;

    ASSERT_EQ(result.metadata.row_groups.size(), 2u);
    const auto& group = result.metadata.row_groups[0];
    EXPECT_EQ(group.num_rows, 3);
    EXPECT_GT(group.total_byte_size, 0);
    ASSERT_EQ(group.columns.size(), 5u);

    // Per-column codecs vary across the fixture (snappy / zstd / uncompressed / gzip).
    EXPECT_EQ(group.columns[0].codec, CompressionCodec::Snappy);
    EXPECT_EQ(group.columns[1].codec, CompressionCodec::Zstd);
    EXPECT_EQ(group.columns[2].codec, CompressionCodec::Uncompressed);
    EXPECT_EQ(group.columns[3].codec, CompressionCodec::Gzip);

    // Dictionary-encoded columns carry a dictionary-page offset; the non-dictionary
    // column (failed_payments) does not.
    EXPECT_TRUE(group.columns[0].has_dictionary_page);
    EXPECT_GT(group.columns[0].dictionary_page_offset, 0);
    EXPECT_FALSE(group.columns[2].has_dictionary_page);

    // Offsets and sizes are populated and ordered within the file.
    for (const auto& chunk : group.columns) {
        EXPECT_GT(chunk.data_page_offset, 0);
        EXPECT_GT(chunk.total_compressed_size, 0);
        EXPECT_GT(chunk.total_uncompressed_size, 0);
        EXPECT_EQ(chunk.num_values, 3);
        EXPECT_FALSE(chunk.encodings.empty());
    }
}

// The parser is a trust boundary: malformed inputs fail with a reason, never a
// crash or an out-of-bounds read.
TEST(ParquetMetadata, RejectsMalformedFiles) {
    EXPECT_FALSE(zetta::parquet::parse_parquet_metadata("").ok());
    EXPECT_FALSE(zetta::parquet::parse_parquet_metadata("PAR1").ok());

    // Right size, wrong leading magic.
    EXPECT_FALSE(zetta::parquet::parse_parquet_metadata(std::string("XXXX\0\0\0\0PAR1", 12)).ok());

    // A valid file with its footer-length corrupted to overrun the file.
    std::string bytes = read_bytes(fixture_path());
    ASSERT_GE(bytes.size(), 8u);
    bytes[bytes.size() - 8] = static_cast<char>(0xff);
    bytes[bytes.size() - 7] = static_cast<char>(0xff);
    const auto result = zetta::parquet::parse_parquet_metadata(bytes);
    EXPECT_FALSE(result.ok());
    EXPECT_NE(result.error.find("footer length"), std::string::npos);
}

// Encrypted footers (PARE magic) are explicitly out of scope and rejected
// clearly rather than misparsed.
TEST(ParquetMetadata, RejectsEncryptedFooter) {
    std::string bytes = read_bytes(fixture_path());
    ASSERT_GE(bytes.size(), 4u);
    bytes.replace(bytes.size() - 4, 4, "PARE");
    const auto result = zetta::parquet::parse_parquet_metadata(bytes);
    EXPECT_FALSE(result.ok());
    EXPECT_NE(result.error.find("encrypted"), std::string::npos);
}
